using System.Windows;using System.Windows.Input;
namespace RhinoContextAssist;
public partial class CommandSearchWindow:Window{readonly List<ContextAction> all;readonly Action<ContextAction> run;public CommandSearchWindow(IEnumerable<ContextAction>a,Action<ContextAction> r){InitializeComponent();all=a.ToList();run=r;Refresh();Query.Focus();}void Query_TextChanged(object s,System.Windows.Controls.TextChangedEventArgs e)=>Refresh();void Refresh(){var q=Query.Text?.Trim()??"";Results.ItemsSource=all.Where(a=>string.IsNullOrEmpty(q)||(a.Label+" "+a.Hint+" "+a.Macro+" "+a.Category).Contains(q,StringComparison.OrdinalIgnoreCase)).Select(a=>new SearchItem(a,$"{a.Icon} {a.Label}",a.Hint)).ToList();}void Results_DoubleClick(object s,MouseButtonEventArgs e){if(Results.SelectedItem is SearchItem x){run(x.Action);Close();}}sealed record SearchItem(ContextAction Action,string Title,string Description);}
